instead of all that complicated code for finding the X and Y angles why not just use this (utilizes splitting the gravity vector and solves for the "triangle" to find the various angles): 

float gForceX, gForceY, gForceZ; //g forces
float angleX, angleY, angleZ;

  Acc_rawX=Wire.read()<<8|Wire.read();
  Acc_rawY=Wire.read()<<8|Wire.read();
  Acc_rawZ=Wire.read()<<8|Wire.read(); 

  gForceX = Acc_rawX / 16384.0;
  gForceY = Acc_rawY / 16384.0; 
  gForceZ = Acc_rawZ / 16384.0;

  Serial.print("   Angle (deg)");
  Serial.print(" Y=");
  Serial.print(180*((atan(gForceY/gForceZ))/3.141592));
  Serial.print(" X=");
  Serial.println(180*((atan(gForceX/gForceZ))/3.141592));


